mapper.select:
/* SQL ID : ExrcsSddnQstnBscDAO.profExrcsSddnQstnBscListPaging 설 명 : 교수연습돌발문항기본목록페이징 */
SELECT ROW_NUMBER() OVER(ORDER BY QSTN.REG_DTTM DESC) AS LINE_NO , QSTN.* , COUNT(QSTN.EXRCS_SDDN_QSTN_BSC_ID) OVER() AS TOTAL_CNT FROM ( SELECT QSTN_BSC.EXRCS_SDDN_QSTN_BSC_ID , CHRT.DGRS_YR , CHRT.DGRS_SMSTR_CHRT , QSTN_BSC.QSTN_TTL , (SELECT COUNT(QSTN_ID) FROM TB_LMS_QSTN WHERE DELYN = 'N' AND EXRCS_SDDN_QSTN_BSC_ID = QSTN_BSC.EXRCS_SDDN_QSTN_BSC_ID AND QSTN_GBNCD = QSTN_BSC.QSTN_GBNCD) AS QSTN_CNT , QSTN_BSC.QSTNS_CMPTNYN , (SELECT LCTR_WKNO FROM TB_LMS_LCTR_WKNO_SCHDL WHERE LCTR_WKNO_SCHDL_ID = QSTN_BSC.LCTR_WKNO_SCHDL_ID) AS LCTR_WKNO , (SELECT MIN(QSTN_SEQNO) FROM TB_LMS_QSTN WHERE EXRCS_SDDN_QSTN_BSC_ID = QSTN_BSC.EXRCS_SDDN_QSTN_BSC_ID) AS QSTN_SEQNO , (SELECT USERNM FROM TB_LMS_USER WHERE USER_ID = QSTN_BSC.RGTR_ID) AS RGTRNM , QSTN_BSC.REG_DTTM FROM TB_LMS_EXRCS_SDDN_QSTN_BSC QSTN_BSC JOIN TB_LMS_SBJCT SBJCT ON QSTN_BSC.SBJCT_ID = SBJCT.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON SBJCT.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID WHERE QSTN_BSC.SBJCT_ID = #{sbjctId} AND QSTN_BSC.QSTN_GBNCD = #{qstnGbncd}
AND LOWER(QSTN_BSC.QSTN_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
ORDER BY QSTN_BSC.REG_DTTM ) QSTN

mapper.insert:
		/*
             SQL ID : ExrcsSddnQstnBscDAO.exrcsSddnQstnBscBulkRegist
             설  명 : 연습돌발문항기본일괄등록
         */
        INSERT ALL

			INTO TB_LMS_EXRCS_SDDN_QSTN_BSC (
	         	  EXRCS_SDDN_QSTN_BSC_ID
				, SBJCT_ID
				, QSTN_TTL
				, QSTN_CTS
				, QSTN_GRP_ID
				, LCTR_WKNO_SCHDL_ID
				, QSTN_GBNCD
				, RGTR_ID
				, REG_DTTM
	         ) VALUES (
	         	  #{item.exrcsSddnQstnBscId}
				, #{item.sbjctId}
				, #{item.qstnTtl}
				, #{item.qstnCts}
				, #{item.qstnGrpId}
				, #{item.lctrWknoSchdlId}
				, #{item.qstnGbncd}
				, #{item.rgtrId}
				, FN_DTTM()
	         )

		SELECT * FROM DUAL

mapper.update:
		/*
             SQL ID : ExrcsSddnQstnBscDAO.exrcsSddnQstnBscModify
             설  명 : 연습돌발문항기본수정
         */
        UPDATE TB_LMS_EXRCS_SDDN_QSTN_BSC SET
        	  MDFR_ID = #{mdfrId}
        	, MOD_DTTM = FN_DTTM()
        	, QSTN_TTL = #{qstnTtl}
			, QSTN_CTS = #{qstnCts}
			, LCTR_WKNO_SCHDL_ID = #{lctrWknoSchdlId}
         WHERE EXRCS_SDDN_QSTN_BSC_ID = #{exrcsSddnQstnBscId}

		/*
             SQL ID : ExrcsSddnQstnBscDAO.exrcsQstnscmptnynBulkModify
             설  명 : 연습문제출제완료여부일괄수정
         */

         UPDATE TB_LMS_EXRCS_SDDN_QSTN_BSC SET
         	  MDFR_ID = #{item.mdfrId}
         	, MOD_DTTM = FN_DTTM()
         	, QSTNS_CMPTNYN = #{item.qstnsCmptnyn}
          WHERE EXRCS_SDDN_QSTN_BSC_ID = #{item.exrcsSddnQstnBscId}
            AND DELYN = 'N'

mapper.insert:
		/*
             SQL ID : ExrcsSddnQstnBscDAO.sddnQuizRegist
             설  명 : 돌발퀴즈등록
         */
        INSERT INTO TB_LMS_EXRCS_SDDN_QSTN_BSC (
	    	  EXRCS_SDDN_QSTN_BSC_ID
			, SBJCT_ID
			, QSTN_TTL
			, QSTN_CTS
			, QSTNS_CMPTNYN
			, LCTR_WKNO_SCHDL_ID
			, QSTN_GBNCD
			, RGTR_ID
			, REG_DTTM
	    ) VALUES (
	    	  #{exrcsSddnQstnBscId}
			, #{sbjctId}
			, #{qstnTtl}
			, #{qstnCts}
			, 'Y'
			, #{lctrWknoSchdlId}
			, #{qstnGbncd}
			, #{rgtrId}
			, FN_DTTM()
	    )

mapper.select:
/* SQL ID : ExrcsSddnQstnBscDAO.admExrcsSddnQstnBscListPaging 설 명 : 관리자연습돌발문항기본목록페이징 */
SELECT ROW_NUMBER() OVER(ORDER BY QSTN.REG_DTTM DESC) AS LINE_NO , QSTN.* , COUNT(QSTN.EXRCS_SDDN_QSTN_BSC_ID) OVER() AS TOTAL_CNT FROM ( SELECT QSTN_BSC.EXRCS_SDDN_QSTN_BSC_ID , QSTN_BSC.SBJCT_ID , ORG.ORGNM , CHRT.DGRS_YR , CHRT.DGRS_SMSTR_CHRT , SBJCT.SBJCTNM , QSTN_BSC.QSTN_TTL , (SELECT COUNT(QSTN_ID) FROM TB_LMS_QSTN WHERE DELYN = 'N' AND EXRCS_SDDN_QSTN_BSC_ID = QSTN_BSC.EXRCS_SDDN_QSTN_BSC_ID AND QSTN_GBNCD = QSTN_BSC.QSTN_GBNCD) AS QSTN_CNT , QSTN_BSC.QSTNS_CMPTNYN , (SELECT LCTR_WKNO FROM TB_LMS_LCTR_WKNO_SCHDL WHERE LCTR_WKNO_SCHDL_ID = QSTN_BSC.LCTR_WKNO_SCHDL_ID) AS LCTR_WKNO , (SELECT MIN(QSTN_SEQNO) FROM TB_LMS_QSTN WHERE EXRCS_SDDN_QSTN_BSC_ID = QSTN_BSC.EXRCS_SDDN_QSTN_BSC_ID) AS QSTN_SEQNO , (SELECT USERNM FROM TB_LMS_USER WHERE USER_ID = QSTN_BSC.RGTR_ID) AS RGTRNM , QSTN_BSC.REG_DTTM FROM TB_LMS_EXRCS_SDDN_QSTN_BSC QSTN_BSC JOIN TB_LMS_SBJCT SBJCT ON QSTN_BSC.SBJCT_ID = SBJCT.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT CHRT ON SBJCT.SMSTR_CHRT_ID = CHRT.SMSTR_CHRT_ID JOIN TB_LMS_ORG ORG ON CHRT.ORG_ID = ORG.ORG_ID AND ORG.USEYN = 'Y' WHERE QSTN_BSC.QSTN_GBNCD = #{qstnGbncd} AND ORG.ORG_ID = #{orgId}
AND CHRT.SMSTR_CHRT_ID = #{smstrChrtId}
AND CHRT.DGRS_YR = #{dgrsYr}
AND QSTN_BSC.SBJCT_ID = #{sbjctId}
AND LOWER(QSTN_BSC.QSTN_TTL) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))
ORDER BY QSTN_BSC.REG_DTTM ) QSTN
